CREATE FUNCTION public.reconcile_workforce_attendance(_org uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid; n integer; BEGIN IF auth.role()='service_role' OR session_user IN ('postgres','supabase_admin') AND auth.uid() IS NULL THEN o:=_org; ELSE o:=public.current_org_id(); IF o IS NULL OR NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') OR _org IS NOT NULL AND _org<>o THEN RAISE EXCEPTION 'Company attendance access required'; END IF; END IF; INSERT INTO public.workforce_shifts(org_id,employee_id,shift_date,scheduled_start,scheduled_end,break_minutes) SELECT s.org_id,s.employee_id,day::date,(day::date+s.shift_start) AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'),((day::date+CASE WHEN s.shift_end<s.shift_start THEN 1 ELSE 0 END)+s.shift_end) AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'),s.break_minutes FROM public.workforce_schedules s LEFT JOIN public.workforce_clock_settings c ON c.org_id=s.org_id CROSS JOIN LATERAL generate_series((now() AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'))::date-1,(now() AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'))::date,interval '1 day') day WHERE s.enabled AND (o IS NULL OR s.org_id=o) AND extract(dow FROM day)=ANY(s.days_of_week) AND EXISTS(SELECT 1 FROM public.payroll_employee_directory e WHERE e.user_id=s.employee_id AND e.org_id=s.org_id AND e.deleted_at IS NULL AND lower(e.status)='active') ON CONFLICT(org_id,employee_id,shift_date) DO NOTHING; INSERT INTO public.workforce_alerts(org_id,shift_id,employee_id,missing_type) SELECT org_id,id,employee_id,CASE WHEN clock_in IS NULL THEN 'clock_in' ELSE 'clock_out' END FROM public.workforce_shifts WHERE (o IS NULL OR org_id=o) AND review_status='pending' AND (clock_in IS NULL AND scheduled_start<now()-interval '15 minutes' OR clock_in IS NOT NULL AND clock_out IS NULL AND coalesce(scheduled_end,clock_in+interval '16 hours')<now()-interval '15 minutes') ON CONFLICT(shift_id,missing_type) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.reconcile_workforce_attendance(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reconcile_workforce_attendance(uuid) TO authenticated,service_role;
CREATE FUNCTION public.review_workforce_shift(_shift uuid,_hours numeric,_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.workforce_shifts; BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') THEN RAISE EXCEPTION 'Attendance manager required'; END IF; SELECT * INTO s FROM public.workforce_shifts WHERE id=_shift AND org_id=public.current_org_id() FOR UPDATE; IF s.id IS NULL OR _hours IS NULL OR _hours<0 OR _hours>24 OR length(trim(coalesce(_notes,'')))<3 OR length(_notes)>500 THEN RAISE EXCEPTION 'Provide verified hours and a review note'; END IF; IF EXISTS(SELECT 1 FROM public.payroll_payslip_directory p JOIN public.payroll_runs r ON r.id=p.payroll_run_id WHERE p.user_id=s.employee_id AND r.status='approved' AND s.shift_date BETWEEN r.period_start AND r.period_end) THEN RAISE EXCEPTION 'This shift has already been paid'; END IF; UPDATE public.workforce_shifts SET approved_hours=round(_hours,4),review_status='reviewed',reviewed_by=auth.uid(),reviewed_at=now(),review_notes=_notes WHERE id=_shift; UPDATE public.workforce_alerts SET resolved_at=now() WHERE shift_id=_shift AND resolved_at IS NULL; INSERT INTO public.audit_logs(org_id,employee_id,action,details) VALUES(s.org_id,s.employee_id,'attendance_reviewed',jsonb_build_object('shift_id',s.id,'hours',_hours,'reviewer',auth.uid())); END $$;
REVOKE ALL ON FUNCTION public.review_workforce_shift(uuid,numeric,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_workforce_shift(uuid,numeric,text) TO authenticated;
CREATE FUNCTION public.workforce_pay_hours(_employee uuid,_start date,_end date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg public.workforce_clock_settings; total numeric:=0; ot numeric:=0; pending integer; cnt integer; BEGIN IF public.employee_org_id(_employee) IS DISTINCT FROM public.current_org_id() OR NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'payroll') THEN RAISE EXCEPTION 'Company payroll access required'; END IF; SELECT * INTO cfg FROM public.workforce_clock_settings WHERE org_id=public.current_org_id(); SELECT count(*),count(*) FILTER(WHERE approved_hours IS NULL),coalesce(sum(approved_hours),0) INTO cnt,pending,total FROM public.workforce_shifts WHERE org_id=public.current_org_id() AND employee_id=_employee AND shift_date BETWEEN _start AND _end; IF cfg.overtime_basis='daily' THEN SELECT coalesce(sum(greatest(0,approved_hours-cfg.overtime_threshold)),0) INTO ot FROM public.workforce_shifts WHERE org_id=public.current_org_id() AND employee_id=_employee AND shift_date BETWEEN _start AND _end; ELSE WITH weeks AS(SELECT date_trunc('week',shift_date) week,sum(approved_hours) hours FROM public.workforce_shifts WHERE org_id=public.current_org_id() AND employee_id=_employee AND shift_date BETWEEN _start AND _end GROUP BY 1) SELECT coalesce(sum(greatest(0,hours-coalesce(cfg.overtime_threshold,40))),0) INTO ot FROM weeks; END IF; RETURN jsonb_build_object('hours',total,'regular',total-ot,'overtime',ot,'pending',pending,'shifts',cnt,'multiplier',coalesce(cfg.overtime_multiplier,1.5),'enabled',coalesce(cfg.attendance_payroll,false)); END $$;
REVOKE ALL ON FUNCTION public.workforce_pay_hours(uuid,date,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.workforce_pay_hours(uuid,date,date) TO authenticated;
CREATE FUNCTION public.validate_workforce_pay(_employee uuid,_start date,_end date,_basic numeric,_ot numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.payroll_employee_directory; h jsonb; rate numeric; expected numeric; overtime numeric; BEGIN SELECT * INTO e FROM public.payroll_employee_directory WHERE user_id=_employee AND org_id=public.current_org_id(); IF EXISTS(SELECT 1 FROM public.workforce_clock_settings WHERE org_id=public.current_org_id() AND attendance_payroll) AND e.hr_details->>'pay_frequency' IN ('Hourly','Daily') THEN PERFORM 1 FROM public.workforce_clock_settings WHERE org_id=public.current_org_id() FOR SHARE; PERFORM 1 FROM public.workforce_shifts WHERE org_id=public.current_org_id() AND employee_id=_employee AND shift_date BETWEEN _start AND _end FOR UPDATE; h:=public.workforce_pay_hours(_employee,_start,_end); IF (h->>'pending')::integer>0 OR (h->>'shifts')::integer=0 THEN RAISE EXCEPTION 'Attendance review required before payroll'; END IF; rate:=coalesce(nullif(e.hr_details->>'pay_rate',''),'0')::numeric; IF e.hr_details->>'pay_frequency'='Daily' THEN IF coalesce(e.std_hours_per_day,0)<=0 THEN RAISE EXCEPTION 'Daily hours required'; END IF; rate:=rate/e.std_hours_per_day; END IF; expected:=round(rate*(h->>'regular')::numeric,2); overtime:=round(rate*(h->>'overtime')::numeric*(h->>'multiplier')::numeric,2); IF rate<=0 OR abs(_basic-expected)>0.01 OR abs(_ot-overtime)>0.01 THEN RAISE EXCEPTION 'Attendance or pay rate changed; refresh payroll'; END IF; ELSE IF abs(_basic-round(coalesce(e.monthly_salary,0)*public.payroll_period_factor(CASE WHEN _start=date_trunc('month',_start)::date AND _end=(date_trunc('month',_start)+interval '1 month - 1 day')::date THEN 'monthly' ELSE 'custom' END,_start,_end),2))>0.01 THEN NULL; END IF; END IF; END $$;
REVOKE ALL ON FUNCTION public.validate_workforce_pay(uuid,date,date,numeric,numeric) FROM PUBLIC;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='approve_payroll_run'; IF position('Salary changed; refresh payroll' in d)=0 THEN RAISE EXCEPTION 'Approval definition changed'; END IF; d:=replace(d,'IF abs((row->>''basic_pay'')::numeric - round(coalesce(p.monthly_salary,0)*f,2))>0.01 THEN RAISE EXCEPTION ''Salary changed; refresh payroll''; END IF;', 'IF EXISTS(SELECT 1 FROM public.workforce_clock_settings WHERE org_id=public.current_org_id() AND attendance_payroll) AND p.hr_details->>''pay_frequency'' IN (''Hourly'',''Daily'') THEN PERFORM public.validate_workforce_pay(p.user_id,_start,_end,(row->>''basic_pay'')::numeric,(row->>''overtime_pay'')::numeric); ELSE IF abs((row->>''basic_pay'')::numeric-round(coalesce(p.monthly_salary,0)*f,2))>0.01 THEN RAISE EXCEPTION ''Salary changed; refresh payroll''; END IF; END IF;'); EXECUTE d; END $$;